import {valkingSnapshot} from '/valking-agent-data.mjs';
import {rankedAgentSnapshot} from '/ranked-agent-data.mjs';
import {metaCompositions} from '/meta-data.mjs';
import {recommend,compositionEvidence,observationsForMap,entryAgents} from '/engine.js';
import {patch,competitiveRotation} from '/game-data.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,view='overview',map='Lotus',selected=[],weight=50,results=[],playerId,teamId='',register=false,ratedOnly=false,observedOnly=false,proMap='',rotationResults=[],metaProvider='',metaFits=[],chartAllMaps=false;
const demo=[['nova','Duelist',{Jett:4,Raze:3,Neon:3,Yoru:2}],['echo','Initiator',{Sova:4,Fade:3,Skye:3,Gekko:2}],['ghost','Controller',{Omen:4,Astra:3,Viper:3,Brimstone:3}],['atlas','Sentinel',{Killjoy:4,Cypher:4,Chamber:2,Sage:3}],['flux','Flex',{'KAY/O':4,Breach:4,Skye:3,Viper:3}],['kairo','Sub',{Jett:3,Raze:4,Neon:4}],['sage','Sub',{Sova:3,Skye:4,Omen:3}]].map((a,i)=>({id:'demo'+i,name:a[0],status:i>4?'Sub':'Starter',role:a[1],tiers:a[2]}));
const names=['Unrated','Flex','Reliable','Comfort','Instalock'];
const colors={Duelist:'#648ba7',Initiator:'#b78160',Controller:'#8168ad',Sentinel:'#669d89'};
async function api(path,body){const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(d.error);return d;}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function members(){return state.team?state.members:demo}function records(){return state.records||[]}function active(){return members().filter(m=>selected.includes(m.id))}
async function load(){state=await api('state'+(teamId?'?team='+encodeURIComponent(teamId):''));teamId=state.team?.id||'';selected=members().filter(m=>m.status==='Starter').slice(0,5).map(m=>m.id);playerId=members()[0]?.id;ratedOnly=state.team?.settings?.ratedOnly===true;observedOnly=state.team?.settings?.observedOnly===true;calculate();render()}
function settings(){return {...state.team?.settings,ratedOnly,observedOnly}}
function calculate(){results=selected.length===5?recommend(active(),records(),map,weight,settings()):[]}
const nav=[['overview','grid','Overview'],['personal','layers','My agent rankings'],['patch','spark','Patch & rules'],['tiers','layers','Tier lists'],['builder','users','Compositions'],['rotation','map','Map rotation'],['chart','grid','Comp chart'],['pro','chart','Pro data'],['meta','chart','Meta sources'],['roster','users','Team roster'],['saved','layers','Saved lineups']];
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',layers:'<path d="m12 2 9 5-9 5-9-5 9-5Z M3 12l9 5 9-5 M3 17l9 5 9-5"/>',users:'<circle cx="9" cy="8" r="4"/><path d="M3 21v-2a6 6 0 0 1 12 0v2 M16 4.5a4 4 0 0 1 0 7 M18 15a5 5 0 0 1 3 4.6V21"/>',chart:'<path d="M4 20V10 M10 20V4 M16 20v-7 M22 20H2"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',plus:'<path d="M12 5v14M5 12h14"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M5 20h14"/>',chevron:'<path d="m9 18 6-6-6-6"/>',spark:'<path d="m12 2 1.7 6.3L20 10l-6.3 1.7L12 18l-1.7-6.3L4 10l6.3-1.7L12 2Z"/>',map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3V6ZM9 3v15M15 6v15"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.grid}</svg>`}
function action(label,attrs='',tone='default'){return `<button class="action action-${tone}" ${attrs}>${label}</button>`}
function initials(name){return esc(name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase())}
function avatar(agent,compact=false){if(['Miks','Veto'].includes(agent))return `<div class="agent-avatar ${compact?'agent-avatar-compact':''}"><span class="new-agent">${esc(agent.slice(0,2).toUpperCase())}</span>${compact?'':`<span>${esc(agent)}</span>`}</div>`;return `<div class="agent-avatar ${compact?'agent-avatar-compact':''}"><img src="/agents/${agent.toLowerCase().replace(/[^a-z]/g,'')}.png" alt="${esc(agent)}">${compact?'':`<span>${esc(agent)}</span>`}</div>`}
function pool(){return Object.fromEntries(Object.keys(state.agents).map(a=>[a,Math.max(0,...members().map(m=>m.tiers[a]||0))]))}
function signals(){const counts={},total=records().reduce((s,r)=>s+r.sample,0),comfort=pool();for(const r of records())for(const a of r.agents)counts[a]=(counts[a]||0)+r.sample;const picks=Object.values(counts).reduce((s,v)=>s+v,0);return {total,overlap:picks?Math.round(Object.entries(counts).reduce((s,[a,n])=>s+(comfort[a]>=3?n:0),0)/picks*100):0,ranks:Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([agent,n])=>({agent,rate:total?Math.round(n/total*100):0}))};}
function render(){document.body.classList.remove('chart-capture');const owner=state.user&&state.team?.owner===state.user.id, teamName=state.team?.name||(state.user?'Your workspace':'Nightfall Protocol');$('#app').innerHTML=`<div class="app-shell"><div class="sidebar-scrim" hidden></div><aside class="sidebar"><div class="sidebar-mobile-close">${action(icon('close'),'data-menu="close" aria-label="Close menu"','ghost')}</div><div class="brand"><div class="brand-mark"><span class="brand-slash brand-slash-left"></span><span class="brand-slash brand-slash-right"></span></div><div><div class="brand-name">STRAT//STACK</div><div class="brand-kicker">VALORANT TEAM OPS</div></div></div><nav class="nav"><div class="nav-label">WORKSPACE</div>${nav.map(([id,i,label])=>`<button class="action action-ghost nav-item ${view===id?'nav-item-active':''}" data-view="${id}" ${view===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="nav-label">YOUR TEAM</div><button class="team-chip" data-action="account"><div class="team-logo">${initials(teamName)}</div><div class="team-copy"><div>${esc(teamName)}</div><span>${members().length} members · ${members().filter(m=>m.status==='Sub').length} subs</span></div>${icon('chevron')}</button><button class="action action-ghost nav-item" data-action="account">${icon('settings')}<span>Settings</span></button><button class="profile" data-action="account"><div class="profile-avatar">${initials(state.user?.name||'Demo player')}</div><div class="profile-copy"><div>${esc(state.user?.name||'Demo workspace')}</div><span>${state.user?(owner?'Team captain':'Team member'):'Sign in to save your progress'}</span></div>${state.user?'<span class="status-dot"></span>':''}</button></div></aside><main class="main"><header class="topbar"><button class="action action-ghost mobile-menu" data-menu="open" aria-label="Open menu">${icon('menu')}</button><div class="page-heading"><h1 class="page-title">${view==='overview'?'Welcome back, '+esc(teamName):nav.find(n=>n[0]===view)[2]}</h1><div class="page-subtitle">${view==='overview'?"Your team intelligence. Here’s where to focus next.":'Build smarter lineups from roster comfort and professional match data.'}</div></div><div class="header-actions">${action(icon('upload')+' IMPORT DATA','data-action="smartimport"')}${action(icon('plus')+' NEW COMPOSITION','data-view="builder"','primary')}</div></header><div class="content">${!state.team?`<div class="demo-notice"><span>${state.storageReady===false?'Demo mode · Accounts and team saves are awaiting database setup.':'Demo team · Explore the workspace, then sign in to save and collaborate.'}</span>${action(state.user?'SET UP TEAM':'SIGN IN','data-action="account"','ghost')}</div>`:''}${view==='personal'?personalView():view==='patch'?patchView(owner):view==='overview'?overview():view==='builder'?builder():view==='rotation'?rotationView():view==='meta'?metaView():view==='chart'?chartView():view==='tiers'?tierView(owner):view==='pro'?proView(owner):view==='roster'?roster(owner):savedView()}<footer class="footer"><span>STRAT//STACK — VALORANT TEAM OPS</span><span>Independent project · Not affiliated with Riot Games</span></footer></div></main></div>`;bind();document.querySelectorAll('[data-menu]').forEach(b=>b.onclick=()=>toggleMenu(b.dataset.menu==='open'));$('.sidebar-scrim').onclick=()=>toggleMenu(false);document.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>showPlan(Number(b.dataset.plan)));document.querySelectorAll('[data-poolagent]').forEach(b=>b.onclick=()=>{view='tiers';render();document.querySelector(`[data-agent="${b.dataset.poolagent}"]`)?.focus()});}
function toggleMenu(open){$('.sidebar').classList.toggle('sidebar-open',open);$('.sidebar-scrim').hidden=!open;if(open)$('[data-menu="close"]').focus();else $('[data-menu="open"]').focus()}
function heading(eyebrow,title,description,button=''){return `<div class="section-intro"><div><div class="eyebrow">${eyebrow}</div><h2 class="section-title">${title}</h2><div class="section-description">${description}</div></div>${button}</div>`}
function tierCard(ratings=pool(),expanded=false,title='Agent comfort tier list',person=null){return `<section class="panel tier-panel ${expanded?'tier-panel-expanded':''}"><div class="panel-heading"><div><div class="eyebrow">${person?'PLAYER DATA':'TEAM DATA'}</div><h2 class="panel-title">${title}</h2></div><span class="updated">${person?esc(person.name):'Best rating across roster'}</span></div><div class="tier-list">${[[4,'Instalock','red'],[3,'Comfort','orange'],[2,'Reliable','amber'],[1,'Flex','blue'],[0,'Unrated','slate']].map(([t,label,tone])=>`<div class="tier-row"><div class="tier-label tier-${tone}">${label}</div><div class="tier-agents">${Object.keys(state.agents).filter(a=>(ratings[a]||0)===t).map(a=>`<button class="agent-button" data-poolagent="${esc(a)}" aria-label="Edit ${esc(a)} rating">${avatar(a)}</button>`).join('')||'<span class="muted">No agents in this tier</span>'}</div></div>`).join('')}</div><div class="panel-footer"><div class="member-stack">${members().slice(0,2).map(m=>`<span>${initials(m.name)}</span>`).join('')}<span>+${Math.max(0,members().length-2)}</span></div><span>${person?'0–4 comfort scale · unrated agents score zero':`Based on ${members().length} player profiles`}</span><button class="action action-ghost text-action" data-view="tiers">EDIT TIERS ${icon('chevron')}</button></div></section>`}
function proSignal(){const s=signals();return `<section class="panel pro-panel"><div class="panel-heading"><div><div class="eyebrow">PRO META SIGNAL</div><h2 class="panel-title">Your pool, in context</h2></div><div class="signal-ring" style="background:conic-gradient(var(--red) ${s.overlap}%,#ece9e6 0)"><span>${s.overlap}</span><small>%</small></div></div><div class="signal-summary">Your roster has a comfort pick for <strong>${s.overlap}% of observed agent picks</strong> in this dataset. Coverage reflects at least one player rated 3 or 4.</div><div class="mini-bars">${s.ranks.slice(0,3).map(r=>`<div class="mini-bar-row"><span>${esc(r.agent)}</span><div><i class="bar-fill" style="width:${r.rate}%"></i></div><b>${r.rate}%</b></div>`).join('')}</div><div class="pro-source"><div class="vct-mark">VLR</div><div><span>Source-linked snapshot</span><small>${s.total} team-map observations · manual refresh</small></div>${action(icon('chevron'),'data-view="pro" aria-label="View professional data"','ghost')}</div></section>`}
function overview(){const ratings=pool(),s=signals(),coverage=Object.values(ratings).filter(t=>t>=3).length;let best;if(active().length===5)best=[map].flatMap(m=>recommend(active(),records(),m,weight,settings())).sort((a,b)=>b.score-a.score)[0];return `<div class="stats-row"><div class="stat"><span>TEAM COVERAGE</span><strong>${coverage} / ${Object.keys(state.agents).length}</strong><small>agents at Comfort or above</small></div><div class="stat"><span>SELECTED MAP FIT</span><strong>${best?esc(best.map):'—'}</strong><small>${best?best.score+'/100 composition fit':'Select five players to compare'}</small></div><div class="stat"><span>META ALIGNMENT</span><strong>${s.overlap}%</strong><small class="positive">coverage of observed agent picks</small></div></div><div class="dashboard-grid">${tierCard()}${proSignal()}${results[0]?resultCard(results[0],0,true):'<div class="panel empty">Select five players in Compositions to see your lineup.</div>'}</div>`}
function safeLink(url){try{const parsed=new URL(url);return ['https:','http:'].includes(parsed.protocol)?esc(parsed.href):'#'}catch{return '#'}}
function professionalEvidence(r,expanded=false){
 const p=r.professional||compositionEvidence(r.agents||r.assignment.map(a=>a.agent),records(),r.map);
 const sources=p.exactSources.length?p.exactSources:p.similarSources;
 return `<section class="professional-evidence"><div class="eyebrow">MATCH EVIDENCE</div><strong>${p.exactSamples?`${p.exactSamples} exact team-map observations`:'No exact five-agent match in this sample'}</strong><p>${p.mapSamples} observations on ${esc(r.map)}${p.from?` · ${esc(p.from)} to ${esc(p.through)}`:''}. Agent popularity contributes to the fit score; an exact match is separate evidence.</p>${sources.length?`<div class="evidence-links">${sources.slice(0,expanded?5:2).map(x=>`<a href="${safeLink(x.source)}" target="_blank" rel="noopener"><strong>${esc(x.team)}</strong><span>${x.shared}/5 agents · ${esc(x.date)}${x.event?' · '+esc(x.event):''}</span>${expanded?`<small>${x.agents.map(esc).join(' · ')}</small>`:''}</a>`).join('')}</div>${!p.exactSources.length?'<small>Related lineups share agents; they do not validate this exact composition.</small>':''}`:'<p>No matching source links yet. Review map coverage in Pro data.</p>'}${externalEvidence(r)}${rankedEvidence(r)}${valkingEvidence(r)}</section>`;
}
function resultCard(r,i,overviewCard=false){return `<article class="panel comp-panel result"><div class="comp-map ${r.map==='Lotus'?'':'map-abstract'}">${r.map==='Lotus'?'<img src="/maps/lotus.jpg" alt="Lotus map">':''}<div class="map-overlay"></div><div class="map-copy"><div class="eyebrow light">RECOMMENDED FOR</div><div class="map-name">${esc(r.map.toUpperCase())}</div><div class="map-meta">${icon('map')}${r.generated?'Patch '+esc(r.patch):r.example?'Illustrative template':'Observed '+esc(r.date)}</div></div><div class="match-pill">${r.score}/100 FIT</div></div><div class="comp-body"><div class="comp-top"><div><h2 class="panel-title">${i===0?'Your strongest lineup':'Alternative '+(i+1)}</h2><div class="comp-subtitle">${esc(r.team)} · ${r.generated?'All-agent search':r.example?'No pro evidence':r.sample+' observations'}</div></div><div class="ai-badge">${icon('spark')} TEAM FIT</div></div><div class="comp-agents">${r.assignment.map(a=>`<div class="comp-agent">${avatar(a.agent,true)}<div><span>${esc(a.agent)}</span><small>${esc(state.agents[a.agent])}</small><small class="assigned" title="${esc(a.player)}">${esc(a.player)} · ${a.tier}/4</small></div></div>`).join('')}</div><div class="comp-footer"><div class="confidence"><span>Player comfort</span><div class="confidence-track"><i style="width:${r.comfort}%"></i></div><b>${r.comfort}%</b></div>${overviewCard?action('VIEW COMPOSITIONS '+icon('chevron'),'data-view="builder"','primary'):view==='saved'?'':action('VIEW LINEUP '+icon('chevron'),`data-plan="${i}"`,'primary')}</div><div class="comp-evidence">${r.generated?`Ranked agent fit ${r.rankedFit??'—'}/100 · Map fit ${r.mapFit}/100 · Patch fit ${r.patchFit}/100 · Agent popularity ${r.evidence}/100`:r.example?'Example only · import pro observations for this map.':r.evidence+'% of dataset samples on this map.'} ${r.source?`<a href="${safeLink(r.source)}" target="_blank" rel="noopener">View source ↗</a>`:''}</div>${professionalEvidence(r)}${(r.warnings||[]).map(w=>`<p class="model-warning">${esc(w)}</p>`).join('')}</div></article>`}
function builderControls(includeMap=true){return `<section class="panel builder-controls">${includeMap?`<div><label class="fieldlabel" for="map">MAP</label><select id="map">${state.maps.map(m=>`<option value="${m}" ${map===m?'selected':''}>${m}${patch.poolStatus[m]?' · '+patch.poolStatus[m]:''}</option>`).join('')}</select></div>`:''}<div><label class="fieldlabel" for="weight">PLAYER COMFORT ${weight}% / RANKED META, MAP, PATCH & PRO DATA ${100-weight}%</label><input id="weight" type="range" min="0" max="100" value="${weight}"></div>${action(icon('spark')+' GENERATE','data-action="generate"','primary')}<label class="toggle-setting"><input id="rated-only" type="checkbox" ${ratedOnly?'checked':''}> Only agents each player has rated</label><label class="toggle-setting"><input id="observed-only" type="checkbox" ${observedOnly?'checked':''}> Only compositions observed in matches</label><fieldset class="lineup-picker"><legend>YOUR FIVE · ${selected.length}/5 SELECTED</legend>${members().map(m=>`<label class="lineup-player"><span class="profile-avatar">${initials(m.name)}</span><span><strong>${esc(m.name)}</strong><small>${m.status}</small></span><input aria-label="Select ${esc(m.name)}" type="checkbox" data-player="${m.id}" ${selected.includes(m.id)?'checked':''}></label>`).join('')}</fieldset></section>`}
function builder(){return `<div class="page-stack">${heading('MAP LAB','Recommended compositions','Find the best unique agent assignment for your five players and this map.',action('SAVE BEST LINEUP','data-action="save"'))}${builderControls()}${results.length?results.map((r,i)=>resultCard(r,i)).join(''):'<div class="panel empty">Select exactly five players. If none appear, add your roster first. If five are selected, rate more agents or rate an entry duelist (Jett, Raze, Neon or Waylay), relax exclusions, or disable the observed-compositions filter.</div>'}<div class="insight-strip">${icon('spark')}<div><strong>Built around your players</strong><span>Exact search across available agents and player assignments. Every recommendation requires Jett, Raze, Neon or Waylay for entry, plus controller, initiator and sentinel coverage. Map and patch weights are editorial estimates; scores are not win probabilities.</span></div></div></div>`}
function rotationView(){
 rotationResults=competitiveRotation.maps.map(m=>active().length===5?recommend(active(),records(),m,weight,settings())[0]||null:null);
 return `<div class="page-stack">${heading('COMPETITIVE MAP POOL','Your best comp. Every map.','One strongest lineup per map, built around the same five players and your team rules.')}<div class="notice">${competitiveRotation.maps.length} maps · Patch ${competitiveRotation.patch} · Rotation checked ${competitiveRotation.verifiedAt}. <a href="${safeLink(competitiveRotation.source)}" target="_blank" rel="noopener">Map pool source ↗</a> · <a href="${safeLink(patch.source)}" target="_blank" rel="noopener">Riot patch notes ↗</a><br>Rotation is updated manually. Fit scores compare lineups under your settings; they are not win probabilities.</div>${builderControls(false)}${active().length!==5?'<div class="notice">Select exactly five players to generate your map rotation. Captains can add players in Team roster.</div>':''}<div class="rotation-grid">${competitiveRotation.maps.map((m,i)=>{const r=rotationResults[i];return `<article class="panel rotation-card" data-rotation-map="${m}"><div class="rotation-header"><div><div class="eyebrow">IN ROTATION</div><h2>${m}</h2></div><div class="rotation-score">${r?r.score:'—'}<small>${r?'/100 FIT':'NO LINEUP'}</small></div></div>${r?`<div class="rotation-players">${r.assignment.map(a=>`<div class="rotation-player">${avatar(a.agent,true)}<div><strong>${esc(a.player)}</strong><span>${esc(a.agent)} · ${esc(state.agents[a.agent])}</span></div><span class="rotation-tier">${a.tier}/4</span></div>`).join('')}</div><div class="rotation-comfort">Player comfort <strong>${r.comfort}%</strong></div>${professionalEvidence(r)}${(r.warnings||[]).map(w=>`<p class="model-warning">${esc(w)}</p>`).join('')}<div class="rotation-actions">${action('LINEUP DETAILS',`data-rotation-plan="${i}"`,'primary')}${action('COMPARE / SAVE',`data-rotation-open="${m}"`)}</div>`:`<div class="empty">${active().length!==5?'Choose five players above.':'No valid lineup with these rules. An entry duelist and all four roles are required. Try relaxing rated-only, observed-only, or agent exclusions.'}</div>`}</article>`}).join('')}</div></div>`;
}
const sourceCatalog=[
 {name:'Valking.gg',url:'https://valking.gg/en/agents',note:'29 patch 13.08 Platinum+ all-map agent rows imported. A separate 5% scoring signal; sample counts are not published.'},
 {name:'U.GG',url:'https://u.gg/val',note:'The requested page returned 403. No data imported.'},
 {name:'Blitz.gg',url:'https://blitz.gg/valorant',note:'The requested page could not be fetched. No data imported.'},
 {name:'VLR.gg',url:'https://www.vlr.gg/stats',note:'Existing match-level snapshot supplies professional agent popularity and exact composition evidence.'},
 {name:'MetaBot.GG',url:'https://metabot.gg/en/valorant/comps/win-rate',note:'347 map-agent statistics across 12 maps power the main optimizer; Icebox has no imported ranked table and Corrode has no Miks row. Also 31 ranked composition rows imported from the accessible page. All ranks and regions; map and patch unspecified. Source says Updated Oct 11.'},
 {name:'ValoHub',url:'https://valohub.co/meta/comps',note:'36 map-specific editorial recommendations imported. Percentages are estimates, not measured win rates. Reviewed by the source for patch 12.10 on May 28, 2026.'},
 {name:'vstats.gg',url:'https://www.vstats.gg/agents?table=comps',note:'No readable composition rows returned by the accessible page. Not imported.'},
 {name:'THESPIKE.GG',url:'https://www.thespike.gg/valorant-stats/agents-compositions',note:'The accessible page returned table headings but no composition rows. Not imported.'},
 {name:'Strats.gg',url:'https://strats.gg/valorant',note:'Strategy and ability-lineup resource. No five-agent composition statistics imported.'}
];
function sourceStats(x){return `<strong>${x.kind==='editorial'?'Editorial estimate':'Ranked statistics'} · ${x.provider==='metabot'?'MetaBot.GG':'ValoHub'}</strong><span>${x.winRate}% ${x.kind==='editorial'?'estimated win rate':'reported win rate'} · ${x.pickRate}% ${x.kind==='editorial'?'estimated pick rate':'reported pick rate'}${x.matches?' · '+x.matches.toLocaleString()+' matches':''}</span><small>${esc(x.map||'Map unspecified')} · ${esc(x.scope)} · Source updated ${esc(x.sourceUpdated)} · ${x.patch?'Patch '+esc(x.patch):'Patch unspecified'} · Imported ${esc(x.checkedAt)}</small>`}
function externalEvidence(r){const picks=new Set(r.agents||r.assignment.map(a=>a.agent));const matches=metaCompositions.filter(x=>(x.map===null||x.map===r.map)&&x.agents.every(a=>picks.has(a)));return matches.length?`<div class="external-evidence"><div class="eyebrow">ADDITIONAL SOURCE CONTEXT</div>${matches.map(x=>`<a href="${safeLink(x.source)}" target="_blank" rel="noopener">${sourceStats(x)}</a>`).join('')}<p>These sources do not establish professional match evidence on ${esc(r.map)}. Their percentages are not your team's predicted win rate or part of the fit score.</p></div>`:''}
function metaView(){
 const candidates=metaCompositions.filter(x=>(!metaProvider||x.provider===metaProvider)&&(!x.map||x.map===map));
 metaFits=candidates.map(x=>{const excluded=[...new Set([...(settings().excluded||[]),...Object.keys(state.agents).filter(a=>!x.agents.includes(a))])];const result=active().length===5?recommend(active(),records(),map,weight,{...settings(),excluded})[0]:null;return {source:x,result}}).sort((a,b)=>(b.result?.score??-1)-(a.result?.score??-1));
 return `<div class="page-stack">${heading('RANKED STATS & EDITORIAL PICKS','Meta sources','Compare published compositions against your five players. Lineups are sorted by team fit, not by mixing incompatible source percentages.')}<div class="notice">Reviewed source snapshot · imported October 15, 2026 · manual refresh. Ranked aggregates and editorial estimates stay separate from VLR professional observations. Map-unspecified statistics are not evidence for this particular map.</div><details class="panel panelbody"><summary>Source coverage & limitations</summary><div class="source-catalog">${sourceCatalog.map(x=>`<p><a href="${safeLink(x.url)}" target="_blank" rel="noopener"><strong>${x.name} ↗</strong></a><br>${x.note}</p>`).join('')}</div></details>${builderControls()}${rankedTable()}<section class="panel panelbody"><label for="meta-provider">Composition source</label><select id="meta-provider"><option value="">All imported sources</option><option value="metabot" ${metaProvider==='metabot'?'selected':''}>MetaBot.GG · ranked statistics</option><option value="valohub" ${metaProvider==='valohub'?'selected':''}>ValoHub · editorial estimates</option></select><p>${metaFits.length} published compositions for ${esc(map)} or with an unspecified map. Team rules and filters apply to the fit calculation.</p></section>${active().length!==5?'<div class="notice">Select exactly five players to calculate assignments and team fit.</div>':''}<div class="rotation-grid">${metaFits.map(({source:x,result:r},i)=>`<article class="panel meta-source-card"><div class="meta-source-stats"><a href="${safeLink(x.source)}" target="_blank" rel="noopener">${sourceStats(x)}</a></div><div class="meta-source-agents">${x.agents.map(a=>`<div>${avatar(a,true)}<span>${esc(a)}</span></div>`).join('')}</div>${r?`<div class="rotation-comfort">Your roster on ${esc(map)}<strong>${r.score}/100 FIT</strong></div><div class="rotation-actions">${action('VIEW PLAYER ASSIGNMENTS',`data-meta-plan="${i}"`,'primary')}</div>`:`<p class="model-warning">${active().length!==5?'Choose five players to fit this lineup.':'No valid assignment under your current filters and team rules.'}</p>`}</article>`).join('')||'<div class="panel empty">No imported compositions for this source and map.</div>'}</div></div>`;
}
function chartView(){
 const players=active(),chartMaps=chartAllMaps?state.maps:competitiveRotation.maps;
 const rows=chartMaps.map(m=>({map:m,result:players.length===5?recommend(players,records(),m,weight,settings())[0]:null}));
 return `<div class="page-stack chart-page">${heading('TEAM CHEAT SHEET','Your compositions at a glance','One row per map. Player columns stay in the same order so everyone can find their pick.',action('SCREENSHOT MODE','data-chart-capture','primary'))}<details class="panel panelbody chart-settings"><summary>Roster & composition settings · ${players.length}/5 players</summary>${builderControls(false)}</details><div class="chart-toolbar"><label for="chart-pool">Maps to display</label><select id="chart-pool"><option value="rotation" ${!chartAllMaps?'selected':''}>Current competitive rotation (${competitiveRotation.maps.length})</option><option value="all" ${chartAllMaps?'selected':''}>All supported maps (${state.maps.length})</option></select><span>Screenshot mode hides navigation and settings. Press Esc to return.</span></div><div class="chart-scroll"><section class="composition-chart" aria-label="Best team compositions by map"><header class="chart-title"><div><div class="eyebrow">STRAT//STACK · ${state.team?'TEAM PLAYBOOK':'DEMO ROSTER'}</div><h2>${esc(state.team?.name||'Nightfall Protocol')}</h2><p>${chartAllMaps?'All maps':'Competitive rotation'} · Best compositions · Patch ${esc(patch.id)}</p></div><div class="chart-stamp">${chartMaps.length} MAPS<small>${new Date().toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</small></div></header><table class="comp-chart-table"><thead><tr><th scope="col">MAP</th>${players.length===5?players.map(p=>`<th scope="col">${esc(p.name)}</th>`).join(''):'<th scope="col" colspan="5">SELECT FIVE PLAYERS IN ROSTER & COMPOSITION SETTINGS</th>'}<th scope="col">FIT</th></tr></thead><tbody>${rows.map(({map:m,result:r})=>`<tr><th scope="row">${esc(m)}${chartAllMaps&&!competitiveRotation.maps.includes(m)?'<small>Outside rotation</small>':''}</th>${r?players.map(p=>{const a=r.assignment.find(a=>a.playerId===p.id);return `<td><div class="chart-pick">${avatar(a.agent,true)}<div><strong>${esc(a.agent)}</strong><small>${entryAgents.includes(a.agent)?'Entry · ':''}${esc(state.agents[a.agent])}</small></div></div></td>`}).join(''):`<td colspan="5" class="chart-unavailable">${players.length!==5?'Select exactly five players':'No balanced entry composition with current filters'}</td>`}<td class="chart-fit">${r?r.score:'—'}${r?'<small>/100</small>':''}</td></tr>`).join('')}</tbody></table><footer class="chart-notes"><span>Comfort ${weight}% / Ranked meta, map, patch & pro data ${100-weight}% · ${ratedOnly?'Rated agents only':'Unrated agents allowed'} · ${observedOnly?'Observed compositions only':'All-agent optimization'}</span><span>Entry + all four roles required; fit is not win probability. Rotation verified ${competitiveRotation.verifiedAt}.</span></footer></section></div><button class="action action-primary chart-exit" data-chart-exit>EXIT SCREENSHOT MODE · ESC</button></div>`;
}
function valkingEvidence(r){return r.weights?.global?`<details class="ranked-evidence"><summary>Valking agent signal · ${r.weights.global.toFixed(0)}% of fit score</summary><p>Patch ${valkingSnapshot.patch} · ${esc(valkingSnapshot.scope)} · Imported ${valkingSnapshot.checkedAt}. These are all-map statistics, not map-specific results.</p>${r.assignment.map(a=>{const x=valkingSnapshot.agents[a.agent];return `<p><strong>${esc(a.agent)}</strong> · ${x?`${x.winRate}% win rate · ${x.pickRate}% pick rate`:'No data; neutral score'}</p>`}).join('')}<a href="${valkingSnapshot.source}" target="_blank" rel="noopener">Source ↗</a></details>`:''}
function rankedEvidence(r){return r.rankedSource?`<details class="ranked-evidence"><summary>Ranked agent data · MetaBot.GG · ${r.weights?.ranked?.toFixed(0)||0}% of fit score</summary><p>${esc(r.rankedSource.scope)} · Updated ${esc(r.rankedSource.updated)} · Patch unspecified · Manual snapshot</p>${r.assignment.map(a=>`<p><strong>${esc(a.agent)}</strong> · ${a.rankedStats?`${a.rankedStats.winRate}% reported win rate · ${a.rankedStats.pickRate}% pick rate · ${a.rankedStats.matches.toLocaleString()} matches`:'No ranked sample on this map; neutral score'}</p>`).join('')}<a href="${safeLink(r.rankedSource.source)}" target="_blank" rel="noopener">View agent statistics for ${esc(r.map)} ↗</a><p>Small samples are pulled toward neutral. Ranked performance informs individual agents, not exact five-agent matches.</p></details>`:''}
function rankedTable(){const data=rankedAgentSnapshot.maps[map];return `<details class="panel panelbody"><summary>Agent statistics used in recommendations · ${esc(map)}</summary>${data?`<p>MetaBot.GG · ${esc(data.scope)} · Updated ${esc(data.updated)} · Imported ${rankedAgentSnapshot.checkedAt}. Patch not specified by source. Default score: 50% comfort, 30% MetaBot map agents, 5% Valking all-map agents, 5% map, 5% patch, 5% pro popularity.</p><a href="${safeLink(data.source)}" target="_blank" rel="noopener">Source ↗</a><div class="table-scroll"><table><thead><tr><th>AGENT</th><th>WIN RATE</th><th>PICK RATE</th><th>MATCHES</th></tr></thead><tbody>${Object.entries(data.agents).sort((a,b)=>b[1].winRate-a[1].winRate).map(([a,r])=>`<tr><td>${esc(a)}</td><td>${r.winRate}%</td><td>${r.pickRate}%</td><td>${r.matches.toLocaleString()}</td></tr>`).join('')}</tbody></table></div>`:'<p>No map-specific ranked data available; the ranked score is neutral.</p>'}</details>`}
function personalView(){return `<div class="page-stack">${heading('YOUR AGENT POOL','My agent rankings','Save your own comfort ratings, then copy them into a captain-managed roster.',action('SAVE MY RANKINGS','data-action="personal-save"','primary'))}${!state.user?'<div class="notice">Sign in to keep these rankings across sessions.</div>':''}<section class="panel panelbody"><div class="tiereditor">${Object.keys(state.agents).map(a=>`<label>${avatar(a,true)}<span>${esc(a)}<select data-personal-agent="${esc(a)}" aria-label="${esc(a)} personal comfort">${names.map((n,t)=>`<option value="${t}" ${t===(state.personal?.[a]||0)?'selected':''}>${n}</option>`).join('')}</select></span></label>`).join('')}</div></section></div>`}
function patchView(owner){const model=state.team?.settings||{};return `<div class="page-stack">${heading('PATCH INTELLIGENCE','Patch '+patch.id,'Verified '+patch.verifiedAt+' · versioned game inputs',owner?action('SAVE TEAM RULES','data-action="patch-save"','primary'):'')}<section class="panel panelbody"><h3>What changed</h3><p>${esc(patch.summary)}</p><a href="${patch.source}" target="_blank" rel="noopener">Official patch notes ↗</a><p class="muted">${esc(patch.note)} Future patches are not automatically imported. Review new notes before using this snapshot for a later patch.</p><div class="patch-changes">${patch.changes.map(c=>`<p><strong>${esc(c.agent)} · ${esc(c.patch)}</strong> — ${esc(c.note)} <span class="tag">${c.delta>0?'+':''}${c.delta} model points</span> <a href="${c.source}" target="_blank" rel="noopener">Source ↗</a></p>`).join('')}</div></section><section class="panel panelbody"><h3>Team rules</h3><p>Exclude unavailable agents and override patch adjustments after review. Blank values use the published model. Overrides apply only to your team.</p><p class="notice">Balanced compositions require an entry duelist (Jett, Raze, Neon or Waylay), plus a controller, initiator and sentinel. The fifth slot is flexible.</p><div class="patch-grid">${Object.keys(state.agents).map(a=>`<div class="patch-rule"><strong>${esc(a)}</strong><label><input type="checkbox" data-exclude-agent="${esc(a)}" ${(model.excluded||[]).includes(a)?'checked':''} ${!owner?'disabled':''}> Exclude</label><label>Patch adjustment<input type="number" min="-50" max="50" step="1" data-patch-agent="${esc(a)}" value="${model.adjustments?.[a]??''}" placeholder="Default" ${!owner?'disabled':''}></label></div>`).join('')}</div>${!owner?'<p class="muted">Create a team to save your captain settings.</p>':''}</section></div>`}
function tierView(owner){const m=members().find(m=>m.id===playerId);if(!m)return '<div class="panel empty">Add players to your roster to rate agents.</div>';const can=!state.team||owner||m.user_id===state.user?.id;return `<div class="page-stack">${heading('ROSTER INTELLIGENCE','Team agent pool','Combine every player’s comfort picks into one team-wide source of truth.',can?`<div class="actions">${action(icon('upload')+' UPLOAD JSON','data-action="uploadtiers"')}${action('SAVE TIERS','data-action="savetiers"','primary')}</div>`:'')}<div><label class="fieldlabel" for="tierplayer">PLAYER PROFILE</label><select id="tierplayer">${members().map(p=>`<option value="${p.id}" ${p.id===m.id?'selected':''}>${esc(p.name)} · ${p.status}</option>`).join('')}</select></div>${tierCard(m.tiers,true,'Agent comfort tier list',m)}${can?`<section class="panel panelbody"><div class="eyebrow">EDIT RATINGS</div><h2 class="panel-title">Make the pool your own</h2><div class="tiereditor">${Object.keys(state.agents).map(a=>`<label>${avatar(a,true)}<span>${esc(a)}<select data-agent="${esc(a)}" aria-label="${esc(a)} comfort">${names.map((n,t)=>`<option value="${t}" ${t===(m.tiers[a]||0)?'selected':''}>${n}</option>`).join('')}</select></span></label>`).join('')}</div><div class="editor-footer">${action('SAVE PREFERENCES','data-action="savetiers"','primary')}</div></section>`:''}</div>`}
function proView(owner){const s=signals(),filtered=records().filter(r=>!proMap||r.map===proMap),dates=records().map(r=>r.date).filter(Boolean).sort();return `<div class="page-stack">${heading('PROFESSIONAL DATASET','Professional signals','Agent trends from the source-linked snapshot and your imported observations.',`<div class="actions">${action('IMPORT FORMAT','data-action="schema"')}${owner?action(icon('upload')+' IMPORT DATA','data-action="import"','primary'):''}</div>`)}<div class="notice">Source-linked competitive matches from ${esc(dates[0]||'—')} to ${esc(dates.at(-1)||'—')}, plus your imports. This sample includes different events and patches; it is not a live feed or the full professional meta.</div><div class="pro-data-grid">${proSignal()}<section class="panel meta-table"><div class="panel-heading"><div><div class="eyebrow">DATASET PICK RATE</div><h2 class="panel-title">Most observed agents</h2></div><span>${s.total} team-map samples</span></div>${s.ranks.slice(0,6).map((r,i)=>`<div class="meta-row"><span class="rank">0${i+1}</span>${avatar(r.agent,true)}<strong>${esc(r.agent)}</strong><span class="meta-role">${esc(state.agents[r.agent])}</span><b>${r.rate}%</b><span class="trend">observed</span></div>`).join('')}</section></div><section class="panel panelbody"><h3>Map coverage</h3><div class="coverage-grid">${state.maps.map(m=>{const n=observationsForMap(records(),m).reduce((sum,r)=>sum+r.sample,0);return `<button data-coverage="${m}" class="${proMap===m?'primary':''}">${m}<strong>${n}</strong><small>${n?'team-map observations':'No samples yet'}</small></button>`}).join('')}</div><label for="pro-map">Filter match sources</label><select id="pro-map"><option value="">All maps</option>${state.maps.map(m=>`<option ${proMap===m?'selected':''}>${m}</option>`).join('')}</select><p class="muted">Showing ${Math.min(100,filtered.length)} of ${filtered.length} records. Select a map to inspect its evidence.</p></section><section class="panel table-scroll"><table><thead><tr><th>TEAM / DATE</th><th>MAP</th><th>COMPOSITION</th><th>SAMPLES</th></tr></thead><tbody>${filtered.slice(0,100).map(r=>`<tr><td><a href="${safeLink(r.source)}" target="_blank" rel="noopener">${esc(r.team)} ↗</a><small>${esc(r.date)}${r.event?' · '+esc(r.event):''}</small></td><td>${esc(r.map)}</td><td>${r.agents.map(esc).join(' · ')}</td><td>${r.sample}</td></tr>`).join('')}</tbody></table></section></div>`}
function showPlan(i,r=results[i]){if(!r)return;modal(`<div class="eyebrow">${esc(r.map)} · LINEUP DETAILS</div><h2>${r.score}/100 team fit</h2><p class="muted">${esc(r.team)}. ${r.generated?'Generated for patch '+esc(r.patch)+'.':r.example?'Illustrative template; no professional evidence.':'Observed '+esc(r.date)+'.'}</p><div class="plan-players">${r.assignment.map(a=>`<div class="plan-player">${avatar(a.agent,true)}<div><strong>${esc(a.player)} → ${esc(a.agent)}</strong><small>${esc(state.agents[a.agent])} · ${names[a.tier]}</small></div></div>`).join('')}</div><p class="muted">Comfort ${r.comfort}/100 · Map fit ${r.mapFit??'—'}/100 · Patch fit ${r.patchFit??'—'}/100 · Agent popularity ${r.evidence}/100.</p>${r.weights?`<p>Score weights: comfort ${r.weights.comfort}%, ranked agents ${r.weights.ranked?.toFixed(1)||0}%, Valking ${r.weights.global?.toFixed(1)||0}%, map ${r.weights.map.toFixed(1)}%, patch ${r.weights.patch.toFixed(1)}%, evidence ${r.weights.evidence.toFixed(1)}%.</p>`:''}<p class="muted">Highest score under this model, not a predicted win rate. Patch ${esc(r.patch||'unversioned')}.</p>${professionalEvidence(r,true)}`)}

function roster(owner){return heading('STRONGER TOGETHER','Your team, every role.','Captains enter the full roster and every player’s agent preferences. Teammates do not need accounts.',`<div class="actions"><button data-action="account">Team settings</button>${owner?'<button class="primary" data-action="addmember">+ Add player</button>':''}</div>`)+`<div class="grid">${members().map(m=>`<article class="panel roster-card"><div class="split"><span class="avatar">${esc(m.name.slice(0,2).toUpperCase())}</span><span class="tag ${m.status==='Sub'?'purple':''}">${esc(m.status)}</span></div><h3>${esc(m.name)}</h3><p class="muted">${Object.values(m.tiers).filter(n=>n>0).length} agents rated · ${m.user_id?'Linked account':'Roster profile'}</p><div class="tieragents">${Object.entries(m.tiers).filter(([,t])=>t>0).sort((a,b)=>b[1]-a[1]).slice(0,3).map(([a,t])=>`<span class="tag purple">${esc(a)} · ${names[t]}</span>`).join('')}</div><button data-tiers="${m.id}">View tier list</button> ${owner?`<button class="flat" data-edit="${m.id}">Edit player</button>${state.captainManaged?`<button class="flat" data-remove="${m.id}">Remove</button>`:''}`:''}</article>`).join('')}</div>`}
function savedView(){return heading('READY FOR MATCH DAY','Your playbook.','Saved lineup snapshots for your next practice or match.')+(state.saved?.length?state.saved.slice().reverse().map(s=>`<div class="resultshead"><h2>${esc(s.map)}</h2><small>${new Date(s.date).toLocaleString()}</small></div>${resultCard(s.result,0)}`).join(''):'<div class="panel empty">No saved compositions yet.<br>Build a lineup, then save it to your team’s playbook.</div>')}
function modal(html){$('#modal').innerHTML='<button class="flat close" data-close aria-label="Close dialog">✕</button>'+html+'<p class="error" id="modalerror" role="alert"></p>';$('#modal').showModal();$('[data-close]').onclick=()=>$('#modal').close();$('#modal').querySelector('form')?.addEventListener('submit',async e=>{e.preventDefault();try{await submit(e.target)}catch(err){$('#modalerror').textContent=err.message}})}
function auth(){if(state.storageReady===false){modal('<h2>Team workspace coming soon</h2><p class="muted">You can explore the demo and build lineups. Accounts and saved teams will be available once the site owner connects persistent storage.</p>');return}modal(`<h2>${register?'Join your next five.':'Welcome back.'}</h2><p class="muted">Sign in to keep your team, ratings, and playbook in sync.</p><form data-form="auth">${register?'<label for="name">Display name</label><input id="name" name="name" required maxlength="60" autocomplete="name">':''}<label for="email">Email</label><input id="email" name="email" type="email" required autocomplete="email"><label for="password">Password · at least 10 characters</label><input id="password" name="password" type="password" minlength="10" maxlength="200" required autocomplete="${register?'new-password':'current-password'}"><button class="primary wide">${register?'Create account':'Sign in'}</button></form><button class="flat wide" id="switchauth">${register?'Already have an account? Sign in':'New to Stratstack? Create account'}</button>`);$('#switchauth').onclick=()=>{register=!register;auth()}}
function account(){if(!state.user)return auth();modal(`<h2>Your workspace</h2><p class="muted">Signed in as ${esc(state.user.email)}</p>${state.teams.length?`<label>Switch team</label><select id="switchteam">${state.teams.map(t=>`<option value="${t.id}" ${t.id===teamId?'selected':''}>${esc(t.name)}</option>`).join('')}</select>`:''}${state.team&&!state.captainManaged?`<div class="notice" style="margin-top:18px">Team join code: <strong>${esc(state.team.code)}</strong><br>Share this code with teammates to let them join as substitutes.</div>`:''}<form data-form="create"><label>New team name</label><input name="name" required maxlength="60" placeholder="Your team name"><button class="wide">Create team</button></form>${state.captainManaged?'<p class="muted">You are captain of each team you create. Add all five players under Team roster.</p>':'<form data-form="join"><label>Join an existing team</label><input name="code" required placeholder="Enter team code"><button class="wide">Join team</button></form>'}<button class="flat wide" id="logout">Sign out</button>`);$('#switchteam')?.addEventListener('change',async e=>{teamId=e.target.value;$('#modal').close();await load()});$('#modal').querySelectorAll('form').forEach((f,i)=>{if(i)f.addEventListener('submit',async e=>{e.preventDefault();try{await submit(f)}catch(err){$('#modalerror').textContent=err.message}})});$('#logout').onclick=async()=>{await api('logout',{});teamId='';$('#modal').close();await load()}}
function editMember(id){const m=members().find(m=>m.id===id);modal(`<h2>${m?'Edit player':'Add a player'}</h2><p class="muted">Create a roster profile and enter this player’s preferences. No teammate account is required.</p><form data-form="member" data-id="${id||''}"><label>Player name</label><input name="name" value="${esc(m?.name)}" required maxlength="60"><label>Roster status</label><select name="status"><option ${m?.status==='Starter'?'selected':''}>Starter</option><option ${m?.status==='Sub'?'selected':''}>Sub</option></select>${!m&&state.backend==='supabase'?'<label><input name="usePersonal" type="checkbox"> Copy my personal rankings to this player</label>':''}<button class="primary wide">Save player</button></form>`)}
const sample=JSON.stringify([{team:'Professional team name',map:'Ascent',agents:['Jett','Sova','KAY/O','Omen','Killjoy'],sample:1,date:'2026-10-01',source:'https://www.vlr.gg/your-match-id'}],null,2);
function importDialog(kind){const tier=kind==='tiers';modal(`<h2>${tier?'Upload player preferences':'Import professional data'}</h2><p class="muted">${tier?'Use agent names as keys, with values 0–4. Upload replaces this player’s ratings.':'Use verified match records. Each composition must have five unique agents. Imports append to your team’s dataset.'}</p><form data-form="${tier?'uploadtiers':'import'}"><label for="upload">Choose a JSON file</label><input id="upload" type="file" accept=".json,application/json"><label>Or paste JSON</label><textarea name="json" required>${esc(tier?JSON.stringify(members().find(m=>m.id===playerId).tiers,null,2):sample)}</textarea><button class="primary wide">Validate & import</button></form>`);$('#upload').onchange=async e=>{const f=e.target.files[0];if(f){if(f.size>100000){$('#modalerror').textContent='File must be smaller than 100 KB.';return}$('#modal textarea').value=await f.text()}}}
async function submit(f){const b=Object.fromEntries(new FormData(f));const type=f.dataset.form;if(type==='auth'){const r=await api('auth',{...b,register});if(r.confirmationRequired){modal(`<h2>Confirm your email</h2><p>${esc(r.message)}</p><p>If your email includes a confirmation code, enter it below. You can also use the confirmation link and return to sign in.</p><form data-form="verify"><input name="email" type="hidden" value="${esc(b.email)}"><label>Confirmation code</label><input name="code" required minlength="6" maxlength="12" autocomplete="one-time-code"><button class="primary wide">Verify email</button></form>`);return}$('#modal').close();await load();if(!state.team)account();return}if(type==='verify'){await api('verify',b);$('#modal').close();await load();account();return}if(type==='create'||type==='join'){const r=await api(type==='create'?'team':'join',b);teamId=r.teamId;}else if(type==='remove'){await api('remove-member',{teamId,id:f.dataset.id});}else if(type==='member'){await api('member',{...b,usePersonal:b.usePersonal==='on',id:f.dataset.id||undefined,teamId});}else if(type==='import'){await api('records',{teamId,records:JSON.parse(b.json)});}else if(type==='uploadtiers'){const t=JSON.parse(b.json);if(!t||typeof t!=='object'||Array.isArray(t)||Object.entries(t).some(([a,v])=>!state.agents[a]||!Number.isInteger(v)||v<0||v>4))throw Error('Use known agent names with integer ratings 0–4.');if(state.team)await api('tiers',{teamId,id:playerId,tiers:t});else members().find(m=>m.id===playerId).tiers=t;}
 const prior=playerId;$('#modal').close();await load();if(type==='uploadtiers'){playerId=prior;render()}toast('Saved successfully');}
function bind(){$('#chart-pool')?.addEventListener('change',e=>{chartAllMaps=e.target.value==='all';render()});$('[data-chart-capture]')?.addEventListener('click',()=>{document.body.classList.add('chart-capture');window.scrollTo(0,0);$('[data-chart-exit]').focus()});$('[data-chart-exit]')?.addEventListener('click',()=>{document.body.classList.remove('chart-capture');$('[data-chart-capture]').focus()});$('#meta-provider')?.addEventListener('change',e=>{metaProvider=e.target.value;render()});document.querySelectorAll('[data-meta-plan]').forEach(b=>b.onclick=()=>showPlan(0,metaFits[Number(b.dataset.metaPlan)]?.result));document.querySelectorAll('[data-rotation-plan]').forEach(b=>b.onclick=()=>showPlan(0,rotationResults[Number(b.dataset.rotationPlan)]));document.querySelectorAll('[data-rotation-open]').forEach(b=>b.onclick=()=>{map=b.dataset.rotationOpen;view='builder';calculate();render()});$('#pro-map')?.addEventListener('change',e=>{proMap=e.target.value;render()});document.querySelectorAll('[data-coverage]').forEach(b=>b.onclick=()=>{proMap=b.dataset.coverage;render()});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});document.querySelectorAll('[data-player]').forEach(b=>b.onchange=()=>{selected=b.checked?[...selected,b.dataset.player]:selected.filter(id=>id!==b.dataset.player);calculate();render()});$('#map')?.addEventListener('change',e=>{map=e.target.value;calculate();render()});$('#observed-only')?.addEventListener('change',e=>{observedOnly=e.target.checked;calculate();render()});$('#rated-only')?.addEventListener('change',e=>{ratedOnly=e.target.checked;calculate();render()});$('#weight')?.addEventListener('change',e=>{weight=Number(e.target.value);calculate();render()});$('#tierplayer')?.addEventListener('change',e=>{playerId=e.target.value;render()});document.querySelectorAll('[data-tiers]').forEach(b=>b.onclick=()=>{playerId=b.dataset.tiers;view='tiers';render()});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=async()=>{const m=members().find(m=>m.id===b.dataset.remove);modal(`<h2>Remove ${esc(m.name)}?</h2><p>This deletes the roster profile and its preferences. Saved lineup snapshots remain.</p><form data-form="remove" data-id="${esc(m.id)}"><button class="primary wide">Remove player</button></form>`)});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editMember(b.dataset.edit));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{try{switch(b.dataset.action){case'personal-save':{if(!state.user){account();break}const tiers=Object.fromEntries([...document.querySelectorAll('[data-personal-agent]')].map(el=>[el.dataset.personalAgent,Number(el.value)]));await api('personal',{tiers});state.personal=tiers;toast('Your agent rankings are saved');break}case'patch-save':{const adjustments=Object.fromEntries([...document.querySelectorAll('[data-patch-agent]')].filter(el=>el.value!=='').map(el=>[el.dataset.patchAgent,Number(el.value)]));const excluded=[...document.querySelectorAll('[data-exclude-agent]:checked')].map(el=>el.dataset.excludeAgent);const model={adjustments,excluded,requireRoles:true,ratedOnly,observedOnly};await api('settings',{teamId,settings:model});state.team.settings=model;calculate();toast('Team rules saved');break}case'account':account();break;case'smartimport':if(!state.team){account();break}if(view==='tiers')importDialog('tiers');else if(state.team.owner===state.user?.id)importDialog('pro');else toast('Only the captain can import professional data.');break;case'addmember':editMember();break;case'generate':if(selected.length!==5)throw Error('Select exactly five players, including substitutes if needed.');calculate();render();toast('Compositions updated for your lineup');break;case'save':if(!state.team){account();break}if(selected.length!==5)throw Error('Select exactly five players.');await api('save',{teamId,players:selected,map,weight,ratedOnly,observedOnly});state.saved=(await api('state?team='+teamId)).saved;toast('Composition added to your playbook');break;case'savetiers':{const t=Object.fromEntries([...document.querySelectorAll('[data-agent]')].map(s=>[s.dataset.agent,Number(s.value)]));const target=members().find(m=>m.id===playerId);if(state.team)await api('tiers',{teamId,id:target.id,tiers:t});target.tiers=t;calculate();render();toast(state.team?'Player preferences saved':'Demo preferences updated · sign in to keep them');break}case'uploadtiers':importDialog('tiers');break;case'import':importDialog('pro');break;case'schema':modal(`<h2>Composition import format</h2><p class="muted">JSON array of records. Replace the example values with observed match data. Sample is the number of times this exact composition was observed.</p><textarea readonly aria-label="JSON import example">${esc(sample)}</textarea>`);break;}}catch(e){toast(e.message)}})}
$('#app').innerHTML='<div class="loading">Loading your workspace…</div>';load().catch(e=>{$('#app').innerHTML='<div class="empty">Unable to load the workspace. Please refresh to retry.</div>';console.error(e)});

document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('chart-capture')){document.body.classList.remove('chart-capture');$('[data-chart-capture]')?.focus()}});
